window.SUMMARY_EXTRAS = {
  hediondos:{category:'Legislação Especial',explanation:'A Lei 8.072/1990 define crimes hediondos e equipara a eles tortura, terrorismo e tráfico ilícito de drogas. A classificação decorre da lei, não da opinião sobre a gravidade do fato.',example:'Homicídio simples não é automaticamente hediondo; será nos casos expressamente previstos, como atividade típica de grupo de extermínio.',bizu:'Monte uma lista fechada dos crimes previstos e revise as consequências processuais separadamente.',mnemonic:'3T equiparados: Tortura, Terrorismo e Tráfico.',trap:'Crime grave ou repulsivo não vira hediondo sem previsão legal.'},
  racismo:{category:'Legislação Especial',explanation:'A Lei 7.716/1989 pune condutas discriminatórias dirigidas a grupos por raça, cor, etnia, religião ou procedência nacional. Diferencie discriminação coletiva das ofensas dirigidas à honra de pessoa determinada.',example:'Impedir acesso a estabelecimento por motivo racial é conduta discriminatória prevista em lei.',bizu:'Procure o verbo da conduta: impedir, negar, recusar, induzir ou incitar.',mnemonic:'R-C-E-R-P: raça, cor, etnia, religião, procedência.',trap:'Não confunda racismo com qualquer conflito ou ofensa sem elemento discriminatório.'},
  abuso:{category:'Legislação Especial',explanation:'A Lei 13.869/2019 exige, em muitos tipos, finalidade específica de prejudicar, beneficiar ou agir por capricho/satisfação pessoal. Divergência na interpretação da lei ou avaliação de fatos, por si só, não configura abuso.',example:'A análise deve verificar sujeito, conduta, finalidade específica e ausência de justificativa legal.',bizu:'Em cada questão, sublinhe o especial fim de agir; ele costuma decidir o item.',mnemonic:'PBC: Prejudicar, Beneficiar, Capricho.',trap:'Não presuma crime apenas porque o ato foi posteriormente anulado.'},
  tortura:{category:'Legislação Especial',explanation:'A Lei 9.455/1997 abrange tortura-prova, tortura-crime, tortura-discriminação, tortura-castigo e omissão em situações previstas. O agente público pode sofrer aumento de pena.',example:'Submeter pessoa sob guarda a intenso sofrimento como castigo pessoal pode configurar tortura-castigo.',bizu:'Classifique pela finalidade: obter informação, provocar crime, discriminar ou castigar.',mnemonic:'PIC-C: Prova, Infração, Discriminação, Castigo.',trap:'Nem todo constrangimento ou lesão é tortura; observe intenso sofrimento e finalidade legal.'},
  eca:{category:'Legislação Especial',explanation:'O ECA adota proteção integral e prioridade absoluta. Criança é pessoa até 12 anos incompletos; adolescente, entre 12 e 18 anos. Ato infracional é conduta descrita como crime ou contravenção.',example:'À criança autora de ato infracional aplicam-se medidas de proteção; ao adolescente podem ser aplicadas medidas socioeducativas.',bizu:'Memorize faixas etárias e separe proteção, ato infracional e direitos fundamentais.',mnemonic:'Criança: antes dos 12; Adolescente: 12 aos 18.',trap:'Internação é excepcional, breve e sujeita às hipóteses legais; não é resposta automática.'},
  maria:{category:'Legislação Especial',explanation:'A Lei Maria da Penha cria mecanismos de prevenção, assistência, proteção e responsabilização na violência doméstica e familiar contra a mulher. Abrange violência física, psicológica, sexual, patrimonial e moral.',example:'Reter documentos ou destruir objetos da vítima pode configurar violência patrimonial.',bizu:'Classifique a situação nas cinco formas de violência antes de analisar a medida cabível.',mnemonic:'F-P-S-P-M: Física, Psicológica, Sexual, Patrimonial, Moral.',trap:'A lei não exige coabitação atual para toda situação; examine unidade doméstica, família ou relação íntima de afeto.'},
  drogas:{category:'Legislação Especial',explanation:'A Lei 11.343/2006 diferencia porte para consumo e tráfico por circunstâncias do fato, quantidade, local, condições, antecedentes e conduta social; não existe um único limite numérico geral que resolva todo caso.',example:'A mesma quantidade pode receber enquadramentos diferentes conforme embalagem, local, instrumentos e demais provas.',bizu:'Não olhe só a quantidade: faça o pacote QLCC — Quantidade, Local, Circunstâncias e Conduta.',mnemonic:'QLCC: Quantidade, Local, Circunstâncias, Conduta.',trap:'O porte para consumo não foi tratado pela lei como simples fato sem consequências; consulte sempre o texto atualizado.'},
  ambiente:{category:'Legislação Especial',explanation:'A Lei 9.605/1998 reúne crimes ambientais e admite responsabilização de pessoas físicas e jurídicas, conforme requisitos legais. Distingue crimes contra fauna, flora, ordenamento urbano, patrimônio cultural e administração ambiental.',example:'A empresa pode responder sem excluir automaticamente a responsabilidade das pessoas físicas participantes.',bizu:'Classifique primeiro o bem protegido: fauna, flora, poluição, urbanismo ou administração.',mnemonic:'Fa-Flo-PU-A: Fauna, Flora, Poluição/Urbanismo, Administração.',trap:'Responsabilidade penal ambiental não se confunde com obrigação civil de reparar o dano.'},
  constituicao:{category:'Direito Constitucional',explanation:'A Constituição organiza o Estado, limita o poder e protege direitos fundamentais. Em questões, identifique se a norma trata de princípio, direito, garantia, competência ou organização dos poderes.',example:'Habeas corpus protege liberdade de locomoção; mandado de segurança protege direito líquido e certo não amparado por habeas corpus ou habeas data.',bizu:'Associe cada remédio constitucional ao bem protegido e a quem pode impetrá-lo.',mnemonic:'HC locomove; HD informa; MS protege direito líquido; MI combate falta de norma.',trap:'Direitos fundamentais não são, em geral, absolutos; conflitos exigem leitura constitucional.'},
  humanos:{category:'Direitos Humanos',explanation:'Direitos humanos baseiam-se na dignidade e possuem universalidade, indivisibilidade, interdependência e historicidade. No uso da força, legalidade, necessidade, proporcionalidade, precaução e responsabilização orientam a atuação.',example:'Uma medida legal ainda deve ser necessária e proporcional ao risco concreto.',bizu:'Resolva casos em sequência: base legal, necessidade, intensidade proporcional e prestação de contas.',mnemonic:'LNPPR: Legalidade, Necessidade, Proporcionalidade, Precaução, Responsabilização.',trap:'Universalidade não significa aplicação mecânica sem considerar contexto e proteção de outros direitos.'},
  pmpe:{category:'Legislação Institucional',explanation:'A legislação da PMPE trata de hierarquia, disciplina, deveres, direitos, proibições e responsabilidades. A leitura deve separar regra, exceção, autoridade competente e consequência.',example:'Em questão disciplinar, identifique primeiro o dever ou proibição e somente depois a consequência prevista.',bizu:'Crie tabelas com quatro colunas: quem, pode/deve, em qual condição, consequência.',mnemonic:'RACE: Regra, Autoridade, Condição, Efeito.',trap:'Evite importar regra de outra corporação ou de lei revogada para o regime específico da PMPE.'},
  penalmilitar:{category:'Direito Penal Militar',explanation:'O estudo começa pelo conceito legal de crime militar e pela relação entre fato, sujeito, circunstância e legislação aplicável. Crimes propriamente e impropriamente militares exigem atenção ao contexto descrito.',example:'Uma conduta prevista também na lei penal comum pode tornar-se crime militar nas hipóteses estabelecidas pela legislação militar.',bizu:'Use uma árvore: conduta prevista? situação militar? sujeito e vítima? serviço/local/função?',mnemonic:'FSSS: Fato, Sujeito, Situação, Serviço.',trap:'A condição de militar, sozinha, não transforma automaticamente todo delito em crime militar.'}
};

