window.BASIC_SUMMARIES.push(
  {"id": "adm-atos-poderes", "category": "Direito Administrativo", "title": "Organização Administrativa, Poderes e Atos Administrativos (CO-FI-FO-MO-OB / PATI)", "source": "Apostila Base & Lei Seca", "page": 1, "explanation": "A Administração Pública organiza-se por Desconcentração (cria órgãos públicos sem personalidade jurídica, com subordinação hierárquica, como PMPE, CBMPE e Secretarias) e por Descentralização (cria entidades da Administração Indireta — FASE: Fundações, Autarquias, Sociedades de Economia Mista e Empresas Públicas — com personalidade jurídica própria e controle finalístico/tutela). O ato administrativo possui 5 requisitos de validade (CO-FI-FO-MO-OB: Competência, Finalidade, Forma, Motivo e Objeto) e 4 atributos clássicos (PATI: Presunção de legitimidade, Autoexecutoriedade, Tipicidade e Imperatividade). Pela Súmula 473 do STF, a Administração pode ANULAR seus próprios atos quando eivados de vícios que os tornem ilegais (efeito ex tunc) ou REVOGÁ-LOS por motivo de conveniência ou oportunidade (efeito ex nunc), respeitados os direitos adquiridos.", "points": ["DesCOncentração = cria Órgãos (subordinação); DesCEntralização = cria Entidades FASE (vinculação/tutela).", "Requisitos do ato (CO-FI-FO-MO-OB): Competência, Finalidade e Forma são vinculados; Motivo e Objeto formam o mérito nos atos discricionários.", "Súmula 473 STF: Anulação = ilegalidade (Administração ou Judiciário, ex tunc); Revogação = conveniência/oportunidade (só Administração, ex nunc).", "Cobrança forçada de multa administrativa NÃO possui autoexecutoriedade (exige execução fiscal judicial)."], "example": "O Poder Judiciário nunca pode revogar um ato administrativo válido de outro Poder por mérito; só pode anulá-lo por ilegalidade.", "bizu": "Para nunca confundir: DesCOncentração tem 'O' de Órgão; DesCEntralização tem 'E' de Entidade.", "mnemonic": "CO-FI-FO-MO-OB (Requisitos) vs. PATI (Atributos) vs. FASE (Indireta).", "trap": "Afirmar que a Polícia Militar é uma autarquia da Administração Indireta (errado: é órgão da Administração Direta)."},
  {"id": "adm-resp-improbidade", "category": "Direito Administrativo", "title": "Responsabilidade Civil do Estado (Art. 37, § 6º, CF) e Improbidade Administrativa (Lei 14.230/21)", "source": "Apostila Base & Lei Seca", "page": 2, "explanation": "Nos termos do art. 37, § 6º, da CF/88, as pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos respondem OBJETIVAMENTE (Teoria do Risco Administrativo) pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de DOLO ou CULPA (responsabilidade subjetiva do agente). Pelo Tema 940 do STF (Dupla Garantia), a vítima deve acionar exclusivamente o Estado, não podendo processar diretamente o servidor. Já na Lei de Improbidade Administrativa (Lei 8.429/92 atualizada pela Lei 14.230/21), foi abolida a modalidade culposa: todos os atos (art. 9º enriquecimento ilícito, art. 10 lesão ao erário e art. 11 violação a princípios) exigem DOLO específico.", "points": ["Art. 37, § 6º, CF/88: Estado responde objetivamente (admite excludentes: culpa exclusiva da vítima, caso fortuito e força maior).", "Tema 940 STF (Dupla Garantia): A ação indenizatória da vítima deve ser proposta contra o Estado, e não contra o agente público.", "Lei 14.230/2021: Exige DOLO específico para qualquer ato de improbidade administrativa (fim da modalidade culposa) e tornou taxativo o rol do art. 11."], "example": "Se uma viatura em perseguição colide com carro de terceiro inocente, o Estado indeniza o particular objetivamente e só cobra do policial em regresso se comprovar dolo ou culpa.", "bizu": "Vítima -> Estado = Objetiva (sem discutir culpa). Estado -> Servidor = Subjetiva (exige dolo ou culpa).", "mnemonic": "Estado = O (Objetiva); Agente = S (Subjetiva). Improbidade = 100% DOLO.", "trap": "Dizer que o ato de improbidade que causa lesão ao erário (art. 10) ainda admite forma culposa."},
  {"id": "penal-teoria-adm", "category": "Direito Penal", "title": "Aplicação da Lei Penal (LUTA), Excludentes de Ilicitude e Crimes contra a Administração Pública", "source": "Apostila Base & Lei Seca", "page": 3, "explanation": "O Código Penal adota a Teoria da Atividade para o tempo do crime (art. 4º) e a Teoria da Ubiquidade para o lugar do crime (art. 6º — mnemônico LUTA). São causas excludentes de ilicitude (art. 23): estado de necessidade, legítima defesa (incluindo a proteção de refém por agente de segurança pública — art. 25, parágrafo único), estrito cumprimento de dever legal e exercício regular de direito. Nos crimes contra a Administração Pública (arts. 312 a 333), o verbo nuclear define o delito: Apropriar-se/Desviar/Subtrair = Peculato (art. 312); EXIGIR vantagem indevida = Concussão (art. 316); SOLICITAR/RECEBER/ACEITAR promessa = Corrupção Passiva (art. 317); Retardar/Deixar de praticar ato de ofício por interesse/sentimento pessoal = Prevaricação (art. 319).", "points": ["Mnemônico LUTA: LUgar do crime = Ubiquidade (art. 6º CP); Tempo do crime = Atividade (art. 4º CP).", "Art. 28 do CP: Emoção, paixão e embriaguez voluntária ou culposa NÃO excluem a imputabilidade penal.", "Peculato Culposo (art. 312, § 3º): reparação do dano ANTES da sentença irrecorrível extingue a punibilidade; DEPOIS reduz a pena pela metade.", "Súmula 610 STF: Há latrocínio consumado quando o homicídio se consuma, ainda que o agente não realize a subtração de bens da vítima."], "example": "Exigir dinheiro de motorista para não aplicar multa é Concussão (art. 316); solicitar ou aceitar dinheiro oferecido é Corrupção Passiva (art. 317).", "bizu": "Sublinhe sempre o verbo da questão: EXIGIR = Concussão; SOLICITAR/RECEBER = Corrupção Passiva; OFERECER/PROMETER (particular) = Corrupção Ativa (art. 333).", "mnemonic": "LUTA (Lugar=Ubiquidade, Tempo=Atividade) e BRUCE LEE (Excludentes de Ilicitude).", "trap": "Afirmar que na tentativa de subtração com morte consumada há apenas tentativa de latrocínio (viola a Súmula 610 do STF)."},
  {"id": "cpp-inquerito-prisoes", "category": "Direito Processual Penal", "title": "Inquérito Policial, Cadeia de Custódia (Art. 158-A) e Prisões (Flagrante, Preventiva e Temporária)", "source": "Apostila Base & Lei Seca", "page": 4, "explanation": "O Inquérito Policial é procedimento administrativo escrito, sigiloso (respeitada a Súmula Vinculante 14 do STF para o advogado), inquisitivo, oficial, oficioso, INDISPONÍVEL (o delegado nunca pode arquivar — art. 17 do CPP) e DISPENSÁVEL (o MP pode oferecer denúncia sem inquérito se já tiver justa causa). A Cadeia de Custódia (art. 158-A) inicia-se com a preservação do local de crime ou detecção do vestígio. No art. 302 do CPP, o flagrante divide-se em Próprio (cometendo ou acaba de cometer), Impróprio/Quase-flagrante (perseguido LOGO APÓS) e Presumido/Ficto (encontrado LOGO DEPOIS com armas/objetos). A Prisão Preventiva (arts. 311 a 316) nunca pode ser decretada de ofício pelo juiz e exige revisão a cada 90 dias.", "points": ["Prazos do IP (Preso / Solto): CPP = 10d / 30d; Lei de Drogas = 30+30d / 90+90d; Justiça Federal = 15+15d / 30d; IPM (CPPM) = 20d / 40+20d.", "Art. 302 CPP: Perseguido LOGO APÓS = Flagrante Impróprio; Encontrado LOGO DEPOIS com instrumentos/armas = Flagrante Presumido.", "Art. 311 e 316 CPP: Juiz não decreta preventiva de ofício; manutenção deve ser revisada a cada 90 dias.", "Prisão Temporária (Lei 7.960/89): cabe apenas na fase de investigação (5+5 dias em crimes comuns; 30+30 dias em hediondos)."], "example": "Na regra geral do CPP (art. 25), a retratação da representação cabe até o OFERECIMENTO da denúncia; na Lei Maria da Penha (art. 16), cabe até o RECEBIMENTO da denúncia em audiência especial.", "bizu": "Perseguido LOGO APÓS = Impróprio (quase-flagrante); Encontrado LOGO DEPOIS = Presumido (ficto).", "mnemonic": "I-D-O-I-S-E: Indisponível, Dispensável, Oficial, Inquisitivo, Sigiloso e Escrito.", "trap": "Dizer que o juiz pode decretar prisão preventiva de ofício durante a instrução processual (foi proibido pelo Pacote Anticrime em 2019)."},
  {"id": "extrav-pacote-policial", "category": "Legislação Extravagante", "title": "Tortura (9.455/97), Abuso de Autoridade (13.869/19), Maria da Penha, Drogas, Hediondos e Racismo", "source": "Apostila Base & Lei Seca", "page": 5, "explanation": "Quadro comparativo das Leis Penais Especiais: (1) Lei de Tortura (9.455/97): crime comum em regra; tortura-omissão tem pena de detenção de 1 a 4 anos; a perda do cargo e a interdição pelo DOBRO do prazo da pena são efeitos AUTOMÁTICOS da condenação. (2) Lei de Abuso de Autoridade (13.869/19): exige dolo específico (prejudicar, beneficiar ou mero capricho); a perda do cargo e inabilitação de 1 a 5 anos NÃO são automáticas (exigem REINCIDÊNCIA específica e motivação na sentença). (3) Lei Maria da Penha (11.340/06): art. 12-C autoriza afastamento do agressor pelo Juiz, Delegado (fora de sede de comarca) ou Policial (fora de sede de comarca e sem delegado), comunicando o juiz em 24h; lesão corporal doméstica é de ação pública INCONDICIONADA (Súmula 542 STJ). (4) Lei 14.532/23: Injúria Racial (art. 2º-A da Lei 7.716/89) é crime inafiançável, imprescritível e de ação pública incondicionada.", "points": ["Perda do cargo: Tortura = AUTOMÁTICA (interdição pelo dobro da pena); Abuso de Autoridade = exige REINCIDÊNCIA específica (inabilitação de 1 a 5 anos).", "Lei de Drogas (11.343/06): art. 28 (consumo pessoal) nunca impõe prisão; tráfico privilegiado (art. 33, § 4º) NÃO é hediondo.", "Crimes Hediondos (8.072/90): Furto só é hediondo com EXPLOSIVO; Roubo só é hediondo com restrição de liberdade, ARMA DE FOGO ou lesão grave/morte (latrocínio).", "ECA (8.069/90): Criança (< 12 anos) que pratica ato infracional recebe apenas medida PROTETIVA (art. 101); medida socioeducativa (art. 112) é exclusiva de adolescente (12 a < 18 anos)."], "example": "Roubo praticado com faca (arma branca) é roubo majorado no CP, mas NÃO é crime hediondo na Lei 8.072/90.", "bizu": "Sempre que a prova comparar Tortura e Abuso de Autoridade, olhe para o efeito da condenação sobre o cargo público.", "mnemonic": "Tortura = Automática (Dobro); Abuso = Reincidência (1 a 5 anos).", "trap": "Afirmar que o porte de drogas para consumo pessoal (art. 28) admite pena de detenção em caso de reincidência."},
  {"id": "geo-pe-mesorregioes", "category": "Geografia de Pernambuco", "title": "Mesorregiões, Clima, Relevo, Hidrografia e Polos Econômicos de Pernambuco", "source": "Apostila Base & Lei Seca", "page": 6, "explanation": "Pernambuco organiza-se em 5 mesorregiões no sentido Leste–Oeste: (1) Região Metropolitana do Recife (RMR) e Litoral: clima tropical úmido (As' — chuvas de outono/inverno), Complexo Industrial Portuário de Suape e Porto Digital; (2) Zona da Mata: dividida em Mata Norte (mais seca, policultura e cana) e Mata Sul (mais úmida e montanhosa, monocultura canavieira); (3) Agreste: zona de transição climática, marcada pelo Planalto da Borborema, pelos Brejos de Altitude (chuvas orográficas em Garanhuns, Triunfo e Brejo da Madre de Deus), pela Bacia Leiteira e pelo Polo de Confecções (Caruaru, Toritama e Santa Cruz do Capibaribe); (4) Sertão Pernambucano / Araripe: clima semiárido (BSh), vegetação de Caatinga e Polo Gesseiro do Araripe (Araripina, Trindade e Ipubi — 95% do gesso do país); (5) Sertão do São Francisco (Petrolina e Lagoa Grande): fruticultura irrigada voltada à exportação (uva e manga) e vitivinicultura tropical.", "points": ["Planalto da Borborema no Agreste: provoca chuvas orográficas a barlavento (brejos de altitude) e semiaridez a sotavento (Sertão).", "Rios de Pernambuco: na RMR/Mata são perenes (Capibaribe, Ipojuca, Una, Jaboatão); no Sertão são temporários/intermitentes (Pajeú, Moxotó, Brígida), salvo o Rio São Francisco (perene).", "Polos econômicos: Petrolina = Fruticultura irrigada; Araripe = Polo Gesseiro; Agreste Setentrional = Polo de Confecções; Ipojuca/Cabo = Suape."], "example": "A questão que associa Araripina e Trindade à produção de gipsita/gesso está correta (Polo Gesseiro do Araripe).", "bizu": "Caruaru/Toritama/Santa Cruz = Confecções (Agreste); Araripina/Trindade/Ipubi = Gesso (Araripe); Petrolina = Fruticultura (São Francisco).", "mnemonic": "Litoral -> Mata -> Agreste (Borborema/Transição) -> Sertão.", "trap": "Inverter o Polo Gesseiro do Araripe com o Polo de Confecções do Agreste ou dizer que o Rio Capibaribe nasce no Sertão (nasce no Agreste, em Poção/Jataúba)."},
  {"id": "fis-bio-cbmpe", "category": "Física", "title": "Física e Biologia Aplicadas ao CBMPE (Termologia, Hidrostática, APH, RCP e Queimaduras)", "source": "Apostila Base & Lei Seca", "page": 7, "explanation": "FÍSICA (Combate a Incêndio e Salvamento): (1) Transmissão de calor: Condução (sólidos, partícula a partícula), Convecção (fluidos líquidos e gases por diferença de densidade — fumaça quente subindo ao teto) e Irradiação (ondas eletromagnéticas, inclusive no vácuo). (2) Hidrostática (Teorema de Stevin): a cada 10 metros de profundidade em água doce, a pressão hidrostática aumenta 1 atm; logo, a pressão TOTAL a 20m é 1 atm (superfície) + 2 atm (água) = 3 atm. (3) Eletricidade: P = U · i e U = R · i (1ª Lei de Ohm). BIOLOGIA / APH: (1) Pequena circulação: Ventrículo Direito (sangue venoso) -> Artéria Pulmonar -> Pulmões (hematose) -> Veias Pulmonares (sangue arterial) -> Átrio Esquerdo. (2) RCP em adultos (SBV): 30 compressões para 2 ventilações (100 a 120/min). (3) Queimaduras: 1º grau (epiderme, eritema sem bolhas), 2º grau (epiderme + derme parcial, dor intensa e FLICTENAS/BOLHAS) e 3º grau (espessura total, placa coriácea/carbonizada).", "points": ["Incêndio em recinto fechado: fumaça e gases quentes sobem por CONVECÇÃO térmica.", "Teorema de Stevin no mergulho: Pressão Total = Pressão Atmosférica (1 atm) + (Profundidade / 10).", "Artéria Pulmonar: sai do ventrículo direito levando sangue VENOSO aos pulmões; Veias Pulmonares trazem sangue ARTERIAL ao átrio esquerdo.", "Queimadura de 2º grau: presença característica de flictenas (bolhas), que nunca devem ser rompidas no APH."], "example": "A 30 metros de profundidade em água doce, o mergulhador suporta 3 atm de pressão hidrostática + 1 atm atmosférica = 4 atm de pressão absoluta.", "bizu": "Flictena (bolha) = Queimadura de 2º Grau. Fumaça subindo = Convecção. 10m de água = +1 atm.", "mnemonic": "Classes de Incêndio: A (Sólidos/Brasa), B (Líquidos/Gases), C (Elétricos energizados), D (Metais pirofóricos), K (Cozinha/Óleos).", "trap": "Esquecer de somar 1 atm da pressão atmosférica quando a questão de mergulho pede a pressão TOTAL ou ABSOLUTA."},
  {"id": "manual-01-ciclo-estudos", "category": "Manuais do Caçador (Método & Estratégia)", "title": "Manual 01 — Do Caos ao Método: Como Funciona o Ciclo de Estudos Dinâmico", "source": "Manual Oficial do Caçador", "page": 1, "explanation": "Estudar muito e não ver evolução quase nunca é falta de esforço: é falta de método. O Cronograma Tradicional (fixo por dia da semana, ex.: 'Segunda às 19h = Português') falha porque qualquer imprevisto no trabalho ou no plantão gera culpa e acumula matérias atrasadas. No Ciclo de Estudos Dinâmico (inspirado no método de aprovados da Estudei), você organiza uma FILA sequencial de blocos (de 45 a 60 minutos). Se terça-feira você não conseguiu estudar, na quarta-feira você simplesmente retoma exatamente do bloco onde parou — sem quebrar o planejamento e garantindo que todas as disciplinas do edital girem de forma equilibrada.", "points": ["Nunca estude apenas 1 disciplina por dia inteiro: alterne 2 a 3 blocos de 45–60 min combinando matérias teóricas (Direito/História) com matérias práticas (RLM/Português).", "Classifique sempre suas Horas Líquidas no cronômetro em 4 modalidades: Teoria (25% do tempo), Lei Seca (25%), Questões (35%) e Revisão (15%).", "Horas Líquidas só contam enquanto você está efetivamente lendo, fazendo questões ou revisando (pause o cronômetro ao levantar ou olhar o celular).", "Matérias de maior peso no edital ou em que sua taxa de acerto está abaixo de 65% entram 2 vezes na mesma volta do ciclo."], "example": "Exemplo de 1 volta de Ciclo Policial (6 blocos): Bloco 1: Português (60m) -> Bloco 2: Constitucional Lei Seca (60m) -> Bloco 3: RLM Questões (45m) -> Bloco 4: Penal/CPP (60m) -> Bloco 5: Legislação Extravagante (60m) -> Bloco 6: História/Geografia de PE + Informática (50m).", "bizu": "Ao finalizar cada bloco no Cronômetro de Foco da aba Hoje, clique em '✓ Concluir Bloco e Girar Ciclo' para o sistema registrar a modalidade e já puxar a próxima matéria da fila.", "mnemonic": "Regra 25-25-35-15: 25% Teoria, 25% Lei Seca, 35% Questões, 15% Revisão.", "trap": "Ficar meses apenas lendo PDF/videoaula ('estudo passivo') sem dedicar pelo menos metade dos blocos à resolução ativa de questões e leitura da lei seca."},
  {"id": "manual-02-dominando-questoes", "category": "Manuais do Caçador (Método & Estratégia)", "title": "Manual 02 — Dominando as Questões e Engenharia Reversa das Bancas", "source": "Manual Oficial do Caçador", "page": 2, "explanation": "Estudar teoria sem praticar questões é como tentar aprender a dirigir apenas lendo o manual do carro. As bancas examinadoras (Instituto AOCP, Cebraspe, FGV, UPENET/IAUPE, IBFC e IDECAN) possuem padrões previsíveis de cobrança e repetem cerca de 70% dos temas de provas anteriores mudando apenas a história do enunciado. Resolver questões com engenharia reversa significa ler não apenas o motivo de a alternativa certa estar correta, mas identificar qual palavra invalidou cada uma das outras alternativas.", "points": ["Instituto AOCP e IBFC: cobram literalidade da Lei Seca (trocam 'salvo' por 'inclusive', 'durante o dia' por 'a qualquer hora', 'detenção' por 'reclusão') e Súmulas Vinculantes do STF.", "Cebraspe: cobra casos hipotéticos ('Determinado agente...') e jurisprudência do STF/STJ; desconfie de palavras restritivas absolutas ('sempre', 'jamais', 'em qualquer hipótese') quando o texto trata de direitos fundamentais.", "FGV Conhecimento: cobra interpretação fina de conjunções ('conquanto', 'porquanto'), casos práticos longos em Penal/Administrativo e Princípio da Casa dos Pombos em RLM.", "UPENET / IAUPE: cobra detalhes históricos e geográficos de Pernambuco (1817, 1824, 1848, Borborema, Polos Econômicos) e literalidade do Estatuto da PMPE (Lei 6.783/74)."], "example": "Ao errar uma questão no simulado ou bateria, ela vai automaticamente para o seu Caderno de Erros. Use o filtro '❌ Questões que errei' toda sexta-feira para limpar suas pendências.", "bizu": "Não passe para o próximo assunto se sua taxa de acerto na bateria de 10 questões ficou abaixo de 60%: leia o diagnóstico de erro passo a passo antes de avançar.", "mnemonic": "L-C-E-R: Ler o comando -> Cortar absurdos -> Encontrar a pegadinha -> Revisar o erro.", "trap": "Medir seu estudo pelo 'número de páginas lidas' em vez de medir pela 'taxa de acerto líquida nas questões da sua banca'."},
    {"id": "manual-04-guia-passo-a-passo", "category": "Manuais do Caçador (Método & Estratégia)", "title": "Manual 04 — Guia Passo a Passo de Uso da Plataforma Jornada do Caçador", "source": "Manual Oficial do Caçador", "page": 4, "explanation": "A plataforma Jornada do Caçador integra em um único painel o Edital Verticalizado, o Ciclo Tático de Estudos, o Cronômetro por Modalidade, a Central de Estudo em Ordem Cronológica, o Banco de Questões por Banca, o Simulador de Aprovação, a Redação IA, o Painel TAF e a Arena Duelo X1. Veja abaixo como utilizar cada módulo na sua rotina diária:", "points": ["Passo 1 (Edital e Planejamento): Em Menu -> Biblioteca, envie o PDF do seu edital na categoria 'Edital do concurso' (100% individual). Depois, na aba Hoje, clique em 'Planejamento' para definir seus minutos diários e dias da semana.", "Passo 2 (Missão Diária, Cronômetro e Ciclo Tático): Na aba Hoje, a Missão Atual, o Ciclo Tático e o Cronômetro trabalham sincronizados na mesma disciplina. Escolha a modalidade (Teoria, Lei Seca, Questões ou Revisão) e cumpra pelo menos 2 etapas (50%) para garantir sua Ofensiva Diária.", "Passo 3 (Central de Estudo e Lei Seca sem PDF): Na aba Estudar, leia os resumos ordenados cronologicamente (Art. 1º -> Art. 2º -> Art. 5º), consulte o Mapa Mental Tático ou use 'Criar Estudo por Texto ou Assunto' na Biblioteca para colar leis secas sem precisar de PDF.", "Passo 4 (Provas em PDF, Gabarito Tardio e Duelo X1): Importe provas com escolha de Caderno (Tipo 1/2/Azul), anexe o gabarito em PDF separado ou use 'Adicionar gabarito depois' (com suporte a questões anuladas). Nos intervalos, desafie colegas ou os Bots das Bancas no Duelo X1 de 60 segundos!"], "example": "Rotina diária ideal na plataforma: 1) Abra a aba Hoje e dê o play no Cronômetro em 'Teoria' -> 2) Clique em '1. Abrir Resumo' no Ciclo Tático -> 3) Clique em 'Questões da Disciplina' abaixo da Missão Atual -> 4) Conclua a missão (+100 XP + até +50 XP de Bônus de Maestria pelo seu índice de acerto).", "bizu": "Vai prestar 2 concursos (ex.: PMPE + CBMPE)? Clique no botão 'Unificar editais' na aba Portais para ativar o Modo Conciliação: os assuntos comuns contam progresso duplo!", "mnemonic": "E-M-Q-R: Edital na Biblioteca -> Missão e Ciclo em Hoje -> Questões da Banca -> Revisão 1-7-30.", "trap": "Concluir missões no clique sem resolver a bateria de questões do tópico: o Termômetro Prático do Edital e o Simulador de Aprovação medem apenas questões realmente resolvidas!"},
  {"id": "manual-03-revisao-pos-edital", "category": "Manuais do Caçador (Método & Estratégia)", "title": "Manual 03 — Estratégia Pós-Edital e Revisão Espaçada (24h, 7 dias e 30 dias)", "source": "Manual Oficial do Caçador", "page": 3, "explanation": "Pela Curva do Esquecimento de Ebbinghaus, o cérebro humano esquece até 70% do que leu em 7 dias se não houver recuperação ativa da memória. Por isso, a revisão não deve ser 'reler o PDF inteiro do zero', mas sim acionar gatilhos rápidos em 3 janelas: 24 horas (Flashcards e Bizus), 7 dias (Bateria curta de 10 questões do tópico) e 30 dias (Simulado misto e revisão do Caderno de Erros). No pós-edital, priorize os tópicos de alta incidência no Raio-X da Banca.", "points": ["Revisão de 24h (5 a 10 min): passe pelos Flashcards e pontos essenciais do assunto estudado no dia anterior.", "Revisão de 7 dias (15 a 20 min): resolva de 5 a 10 questões oficiais da banca sobre o tema sem consultar o resumo.", "Revisão de 30 dias (30 min): refaça as questões que você errou naquele mês usando o filtro '❌ Questões que errei'.", "Acompanhe no Mapa do Edital as duas barras: Cobertura Teórica (% lido) e Cobertura Prática (% testado em questões) devem caminhar juntas!"], "example": "Se você estudou 'Inquérito Policial' hoje, amanhã (24h) revise os prazos (10d/30d) nos flashcards; na próxima semana (7d), faça 10 questões de Inquérito Policial na aba Questões.", "bizu": "Fique atento ao Sino de Notificações no topo do site: ele avisa automaticamente quais tópicos completaram 24h, 7 dias ou 30 dias desde o seu estudo!", "mnemonic": "Ciclo 1-7-30: 1 dia (Flashcards), 7 dias (Questões), 30 dias (Caderno de Erros).", "trap": "Querer fechar 100% da teoria do edital sem revisar nada no caminho e chegar na semana da prova sem lembrar o que estudou no primeiro mês."}
);
